    "source": "maths game(題目庫)/P6/圓周.docx",
    "question": "一個長方形的長是 20cm、闊是 10cm。如果以兩條較短的邊為直徑，分別向長方形外側各接一個半圓，拼成一個運動場形狀的平面圖形。取 π=3.14，這個圖形的周界是多少厘米？",
